        echo "WARNING: config not found, skipping: $config_file"
        continue
    fi

    sbatch \
        --nodes=1 \
        --ntasks=1 \
        --cpus-per-task=40 \
        --mem=100G \
        --time=1:00:00 \
        --output="/gpfs/mskmind_ess/limr/repos/paladin-dev/logs/pickle_%A_%a.out" \
        --error="/gpfs/mskmind_ess/limr/repos/paladin-dev/logs/pickle_%A_%a.err" \
        --qos=premium \
        --job-name="pkl_${run_id}" \
        --gres=gpu:1 \
